-    __ vluxei64_v(as_VectorRegister($dst$$reg), as_Register($mem$$base),
-                  as_VectorRegister($tmp$$reg), Assembler::v0_t);
+    gatherScatter64(masm, false, as_VectorRegister($dst$$reg), as_VectorRegister($idx$$reg),
